{
  "technical_and_design_decisions": [
    "Leverage existing Spring XD and Spring Cloud Stream module architecture and coding conventions without a full rewrite.",
    "For U1, implement a binding configuration resolver that supports multiple external system instances of the same binder type (e.g., multiple Kafka/Rabbit clusters) using Spring Cloud Stream's multi-binder support.",
    "For U2, replace NameNodeProxies.createNonHAProxy with Hadoop's HA-aware proxy creation (ConfiguredFailoverProxyProvider / NameNodeProxies.createProxy) when HA configuration is present, while preserving non-HA behavior.",
    "For U3 and U4, port Cassandra and analytic-pmml modules into the spring-cloud-stream repository, adapting them to the Spring Cloud Stream module API (sink/processor) with Spring Boot auto-configuration.",
    "For U5 and U6, extend the Spring XD admin REST API with JSON endpoints that derive job composition flag and graph from the existing job repository metadata.",
    "For U7 and U8, enhance the existing Angular-based Spring XD dashboard to consume the new endpoints, differentiate composed vs single jobs visually, and provide correct navigation to detail pages.",
    "Use JUnit, Spring Test, and Testcontainers (or embedded services) for automated backend and module tests; keep backward compatibility."
  ],
  "assumptions": [
    "Development environment (JDK compatible with target branch, Maven/Gradle, source repos) is already available; no infrastructure or production deployment is included.",
    "The term 's-c-s repo' refers to the spring-cloud-stream (or spring-cloud-stream-app-starters) repository and its current module conventions.",
    "Existing job composition metadata is sufficient to derive the flag and graph; no new job storage schema changes are required.",
    "UI work is limited to the existing Spring XD dashboard; no new UI framework or major redesign is introduced.",
    "The Spring Framework 6 / Java 17 background information is contextual; upgrading the affected legacy modules to Spring Framework 6 / Java 17 is out of scope for this increment.",
    "Effort estimates represent one developer’s focused workdays and exclude holidays, meetings, and elapsed calendar time."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Analysis and detailed design",
      "activity_description": "Explore the relevant Spring XD and Spring Cloud Stream codebases, confirm requirements for all user stories, and produce a detailed design and task breakdown for the increment.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "Multiple external systems for same binding type (U1)",
      "activity_description": "Implement configuration and runtime support to connect to multiple external systems of the same binding type, enabling reading from one and writing to another, with unit and integration tests.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "HDFS HA namenode support for custom modules (U2)",
      "activity_description": "Modify HDFS module deployment/location code to honor namenode HA configuration instead of always using createNonHAProxy, and add tests with HA configuration.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "Port Cassandra module as sink (U3)",
      "activity_description": "Relocate and adapt the Cassandra module from Spring XD to the spring-cloud-stream repo as a sink module, including API changes, configuration, and tests.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A5",
      "activity_name": "Port analytic-pmml module as processor (U4)",
      "activity_description": "Relocate and adapt the analytic-pmml module from Spring XD to the spring-cloud-stream repo as a processor module, including API changes, configuration, and tests.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A6",
      "activity_name": "REST endpoint for job composition flag (U5)",
      "activity_description": "Implement a REST endpoint that returns a flag indicating whether a job is standalone or part of a parent-child composition, with service and controller tests.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "REST endpoint for job composition graph (U6)",
      "activity_description": "Implement a REST endpoint that returns the job composition graph (nodes and edges) for parent-child relationships, with service and controller tests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "UI visual differentiation of composed jobs (U7)",
      "activity_description": "Update the dashboard to visually differentiate job-composition workflows from single jobs using the new flag/graph endpoints.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A9",
      "activity_name": "UI navigation to job detail pages (U8)",
      "activity_description": "Update dashboard routing and click handling so users can navigate to the detail page of a job whether it is singular or part of a composed job.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration and system testing",
      "activity_description": "Perform end-to-end integration testing across all new features and ported modules, and fix defects found during testing.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation and examples",
      "activity_description": "Write or update README, user documentation, and example configurations for multi-binder support, HDFS HA, ported modules, and job composition REST/UI features.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A12",
      "activity_name": "Build, packaging, and release prep",
      "activity_description": "Verify builds, run full CI checks, package artifacts, and prepare the increment for release (no production deployment).",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 47
  }
}

